import sqlite3,json
c=sqlite3.connect('analytics.db')
S=['install','tutorial_complete','first_match','purchase']
ev={}
for u,n,t in c.execute('select user_id,name,ts from events'): ev.setdefault(u,{}).setdefault(n,[]).append(t)
F={};
for u,p in c.execute('select user_id,platform from users where is_test=0'):
    F.setdefault(p,[0]*4)
    prev=''
    for i,s in enumerate(S):
        v=[t for t in ev.get(u,{}).get(s,[]) if t>=prev]
        if not v:break
        prev=min(v);F[p][i]+=1
out={'funnel':{p:dict(zip(S,v)) for p,v in F.items()}}
bd={}
for p,v in F.items():
    r=[v[i]/v[i-1] for i in range(1,4)];print(p,v,r)
    bd[p]=S[1+r.index(min(r))]
out['biggest_drop']=bd
json.dump(out,open('result.json','w'),indent=1);print(out)

